function btn(text,action,cls='btn'){return `<button class="${cls}" data-action="${action}">${text}</button>`}
function panelHead(title,route){return `<div class="panel-head"><h2>${title}</h2>${route?`<a class="text-link" href="#${route}">VIEW ALL →</a>`:''}</div>`}
function newsRow(n){return `<article class="news-row" data-action="open-news" data-title="${n.title}"><div class="news-thumb" style="background-image:url('${n.image}')"></div><div class="news-copy"><span class="tag">${n.tag}</span><h3>${n.title}</h3><p>${n.desc}</p><div class="meta-row"><span>◷ ${n.time}</span><span>▤ ${Math.floor(70+Math.random()*500)}</span></div></div></article>`}
function tournamentRow(t){return `<div class="tournament-row"><div class="date-block"><small>${t.date.split(' ')[0]}</small><b>${t.date.split(' ')[1]}</b></div><div class="tournament-info"><b>${t.name}</b><small class="prize">${t.prize} Prize Pool</small><small>${t.teams} · ${t.format}</small></div><div style="display:flex;flex-direction:column;gap:8px;align-items:flex-end"><span class="status ${t.status==='LIVE'?'live':t.status==='OPEN'?'open':''}">${t.status}</span><button class="btn btn-outline" data-action="tournament" data-name="${t.name}">VIEW</button></div></div>`}
function liveMatch(a,b,score,map){return `<div class="live-match"><div class="match-league"><span>FL ASH PRO LEAGUE · ${map.toUpperCase()}</span><span class="live-label">● LIVE</span></div><div class="score-line"><div class="team-mini"><span class="team-emblem">${a.slice(0,2).toUpperCase()}</span><span>${a}</span></div><div class="score">${score.split(':')[0]}<small>:</small>${score.split(':')[1]}</div><div class="team-mini right"><span>${b}</span><span class="team-emblem">${b.slice(0,2).toUpperCase()}</span></div></div><div class="match-foot"><span>BO3 · Round 15</span><button class="btn btn-outline" data-action="watch" data-match="${a} vs ${b}">▶ WATCH LIVE</button></div></div>`}
function friendRows(limit=4){return friends.slice(0,limit).map(f=>`<div class="friend-row"><div class="friend-avatar ${f[2]==='busy'?'busy':''}">${f[0].slice(0,1).toUpperCase()}</div><div class="friend-info"><b>${f[0]}</b><small class="${f[1]==='In Match'?'inmatch':''}">${f[1]}</small></div><span class="online-count">●</span></div>`).join('')}
function historyRows(limit=3){return matches.slice(0,limit).map(m=>`<div class="history-row"><span class="result-mark ${m.result}">${m.result==='win'?'✓':'×'}</span><div class="history-info"><b>${m.map} <span style="color:#737987;font-weight:500">· ${m.mode}</span></b><small>${m.time} · ${m.elo}</small></div><span class="history-score ${m.result}">${m.score}</span></div>`).join('')}
function profilePanel(){return `<section class="panel profile-card">${panelHead('MY PROFILE','profile')}<div class="profile-cover"></div><div class="profile-main"><div class="avatar">P</div><div class="profile-name">Pashayev <small>LVL 07 · <i style="color:var(--orange);font-style:normal">◆ Gold II</i></small></div><div class="rank-badge"><span>7</span></div></div><div style="margin-top:15px;display:flex;justify-content:space-between;color:#858b97;font-size:9px;margin-bottom:6px"><span>XP TO LEVEL 8</span><span>1,640 / 2,400</span></div><div class="progress"><span style="width:68%"></span></div><div class="stat-strip"><div><span>Matches</span><b>286</b></div><div><span>Win Rate</span><b>58%</b></div><div><span>ELO</span><b>1,642</b></div></div></section>`}
function rankPanel(){return `<section class="panel rank-progress">${panelHead('RANK PROGRESS')}<div class="rank-top"><div class="rank-medal">♛</div><div class="rank-detail"><small>GOLD II · LEVEL 07</small><b>1,642 ELO</b><div class="elo-line"><span>Next rank: Gold III</span><span>1,642 / 1,800</span></div><div class="progress"><span style="width:79%"></span></div></div></div><div style="margin:13px 0 0 70px;color:#838995;font-size:9px">NEXT REWARD <b style="color:#dddfe4;display:block;margin-top:4px">Diamond Badge · 158 ELO to go</b></div></section>`}
function home(){return `<div class="grid-home"><div class="column"><section class="hero"><div class="hero-content"><span class="eyebrow">CM CLIENT MOBILE · SEASON 01</span><h1>COMPETE<span>IMPROVE</span>BE THE BEST</h1><p>Твоя игра. Твой рейтинг. Твоя история. Докажи свой уровень на арене FlasH.</p>${btn('PLAY NOW　→','route-play','btn btn-hot')}<div class="hero-meta"><span><strong>SEASON 01</strong></span><span>● 24,812 PLAYERS ONLINE</span></div></div></section><section class="panel">${panelHead('NEWS FEED','news')}<div class="news-list">${news.slice(0,4).map(newsRow).join('')}</div></section><section class="panel">${panelHead('RECENT MATCHES','matches')}<div class="match-history-list">${historyRows(4)}</div></section></div><div class="column"><section class="panel">${panelHead('ONGOING MATCHES','matches')}${liveMatch('Night Wolves','Shadow Squad','12:9','Mirage')}${liveMatch('Real Kings','Vortex','8:5','Dust 2')}${liveMatch('Fatality','Unity','6:3','Inferno')}</section><section class="panel">${panelHead('UPCOMING TOURNAMENTS','tournaments')}<div class="tournament-list">${tournaments.slice(0,3).map(tournamentRow).join('')}</div></section>${rankPanel()}<section class="panel">${panelHead('QUICK PLAY','play')}<div class="quick-play"><div class="mode-select"><button class="mode selected" data-mode="5v5 Ranked"><b>5v5</b><small>RANKED</small></button><button class="mode" data-mode="5v5 Unranked"><b>5v5</b><small>CASUAL</small></button><button class="mode" data-mode="2v2"><b>2v2</b><small>WINGMAN</small></button></div><div class="select-line"><span>Region</span><select id="home-region"><option>Europe</option><option>CIS</option><option>Middle East</option></select></div>${btn('FIND MATCH →','find-match','btn btn-hot full')}</div></section></div><div class="column home-right">${profilePanel()}<section class="panel">${panelHead('FRIENDS ONLINE','friends')}<div class="friends-list">${friendRows(5)}</div><div style="padding:12px 14px">${btn('VIEW ALL FRIENDS →','route-friends','btn btn-ghost full')}</div></section><section class="panel">${panelHead('TOP PLAYERS','leaderboard')}<div class="friends-list">${players.slice(0,4).map((p,i)=>`<div class="friend-row"><b class="rank-number ${i<3?'top':''}">#${p[0]}</b><div class="friend-avatar">${p[1][0].toUpperCase()}</div><div class="friend-info"><b>${p[1]}</b><small>${p[3]} ELO</small></div></div>`).join('')}</div></section></div></div>`}
function playPage(){return `<div class="page-title"><div><h1>PLAY / MATCHMAKING</h1><p>Выбери режим, карту и найди соперников своего уровня.</p></div><span class="pill good">● MATCHMAKING ONLINE</span></div><div class="play-layout"><div class="column"><section class="play-hero"><span class="eyebrow">RANKED SEASON 01</span><h2>YOUR NEXT WIN STARTS HERE</h2><p>Поднимай ELO, открывай новые ранги и доказывай своё мастерство в честных матчах.</p>${btn('FIND MATCH →','find-match','btn btn-hot')}</section><section class="panel"><div class="panel-head"><h2>1. SELECT GAME MODE</h2><span class="pill">EUROPE SERVERS</span></div><div class="quick-play"><div class="mode-select">${[['5v5 Ranked','RANKED'],['5v5 Unranked','CASUAL'],['2v2','WINGMAN'],['Custom','PRIVATE']].map((m,i)=>`<button class="mode ${state.mode===m[0]?'selected':''}" data-mode="${m[0]}"><b>${m[0]}</b><small>${m[1]}</small></button>`).join('')}</div><label class="field-label">REGION</label><select id="play-region" class="form-input"><option ${state.region==='Europe'?'selected':''}>Europe</option><option ${state.region==='CIS'?'selected':''}>CIS</option><option ${state.region==='Middle East'?'selected':''}>Middle East</option></select><div style="display:flex;justify-content:space-between;align-items:center;margin-top:15px;color:#7f8591;font-size:10px"><span>Estimated queue time</span><b style="color:#eee">~ 00:42</b></div></div></section><section class="panel"><div class="panel-head"><h2>2. SELECT MAPS</h2><span class="pill" id="map-count">${state.maps.length} SELECTED</span></div><div class="quick-play"><p style="font-size:10px;color:#888e99;margin:0 0 12px">Выбери карты, на которых хочешь играть. Минимум одна карта.</p><div class="map-grid">${Object.entries(mapImages).map(([name,img])=>`<div class="map-card ${state.maps.includes(name)?'selected':''}" data-map="${name}" style="background-image:url('${img}')"><small>${state.maps.includes(name)?'✓ SELECTED':'MAP'}</small><span>${name.toUpperCase()}</span></div>`).join('')}</div></div></section></div><div class="column"><section class="panel" id="queue-panel">${panelHead('QUEUE SUMMARY')}<div class="quick-play"><div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0 13px;border-bottom:1px solid #292d36"><div><span class="eyebrow">CURRENT MODE</span><h3 id="summary-mode" style="margin:7px 0 0;font-size:15px">${state.mode}</h3></div><div class="rank-badge"><span>7</span></div></div><div class="select-line"><span>Region</span><b id="summary-region" style="color:#e8e9ed">${state.region}</b></div><div class="select-line"><span>Your ELO</span><b style="color:var(--orange)">1,642</b></div><div class="select-line"><span>Maps selected</span><b id="summary-maps" style="color:#e8e9ed">${state.maps.join(', ')}</b></div><div class="select-line"><span>Party</span><b style="color:#e8e9ed">1 / ${state.mode==='2v2'?'2':'5'} players</b></div><div style="padding-top:12px;border-top:1px solid #292d36;margin-top:10px">${btn('FIND MATCH →','find-match','btn btn-hot full')}<p style="font-size:9px;color:#6e7480;line-height:1.6;margin:11px 0 0">Начав поиск, ты принимаешь правила честной игры FlasH.</p></div></div></section><section class="panel">${panelHead('MATCHMAKING STATUS')}<div class="quick-play"><div style="display:flex;gap:9px;align-items:center"><span class="live-dot"></span><b style="font-size:11px">All systems operational</b></div><p style="color:#838995;font-size:10px;line-height:1.6">Europe · 18 servers online<br>Average ping: 24 ms<br>Anti-cheat: Active</p></div></section><section class="panel">${panelHead('RANKED REWARDS')}<div class="quick-play"><div class="rank-top"><div class="rank-medal">♛</div><div class="rank-detail"><small>SEASON REWARD</small><b>Gold II Badge</b><small>Win your next 3 matches to unlock a bonus mission.</small></div></div></div></section></div></div>`}
function matchesPage(){return `<div class="page-title"><div><h1>MATCH HISTORY</h1><p>История матчей, результаты и изменение рейтинга.</p></div>${btn('↓ EXPORT CSV','export-matches','btn btn-ghost')}</div><div class="stats-grid">${metric('MATCHES PLAYED','286','↗ 12 this week')}${metric('WIN RATE','58%','↗ 3.2% this month')}${metric('AVG. K/D','1.31','↗ 0.08 this season')}${metric('CURRENT ELO','1,642','↗ +37 this week')}</div><section class="panel"><div class="panel-head"><h2>ALL MATCHES</h2><span class="pill">SEASON 01</span></div><div class="filter-bar" style="padding:12px 13px 0"><select class="filter-select" id="match-filter"><option value="all">All results</option><option value="win">Victory</option><option value="loss">Defeat</option></select><select class="filter-select" id="map-filter"><option value="all">All maps</option>${Object.keys(mapImages).map(m=>`<option>${m}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table" id="matches-table"><thead><tr><th>RESULT</th><th>MAP / MODE</th><th>SCORE</th><th>K / D / A</th><th>ELO CHANGE</th><th>TIME</th></tr></thead><tbody>${matches.map(m=>`<tr data-result="${m.result}" data-map="${m.map}"><td><span class="pill ${m.result==='win'?'good':'bad'}">${m.result==='win'?'VICTORY':'DEFEAT'}</span></td><td>${m.map}<small style="display:block;color:#737986;margin-top:4px">${m.mode}</small></td><td><b>${m.score}</b></td><td>${m.kda}</td><td style="color:${m.result==='win'?'#5ed99a':'#ff6279'}">${m.elo}</td><td>${m.time}</td></tr>`).join('')}</tbody></table></div></section>`}
function metric(title,value,change){return `<div class="metric-card"><span class="metric-icon">↗</span><small>${title}</small><strong>${value}</strong><em>${change}</em></div>`}
function leaderboard(){return `<div class="page-title"><div><h1>LEADERBOARD</h1><p>Лучшие игроки FlasH в текущем сезоне.</p></div><span class="pill">● LIVE RANKINGS</span></div><div class="stats-grid">${metric('PLAYERS RANKED','24,812','Across all regions')}${metric('TOP ELO','2,841','s1mple')}${metric('YOUR RANK','#1,284','Global')}${metric('YOUR ELO','1,642','Gold II')}</div><section class="panel">${panelHead('GLOBAL RANKING')}<div class="filter-bar" style="padding:12px 13px 0"><select class="filter-select" id="leader-region"><option>Global</option><option>Europe</option><option>CIS</option><option>Middle East</option></select><select class="filter-select"><option>Season 1</option><option>All time</option></select><input class="form-input" id="leader-search" placeholder="Search player..." style="width:180px;padding:8px 10px;font-size:10px;margin-left:auto"></div><div class="table-wrap"><table class="data-table" id="leader-table"><thead><tr><th>RANK</th><th>PLAYER</th><th>LEVEL</th><th>ELO</th><th>MATCHES</th><th>WIN RATE</th><th>K/D</th></tr></thead><tbody>${players.map((p,i)=>`<tr data-player="${p[1].toLowerCase()}"><td><span class="rank-number ${i<3?'top':''}">#${p[0]}</span></td><td class="player-cell"><span class="tiny-avatar">${p[1][0].toUpperCase()}</span>${p[1]} ${i===0?'<span style="color:var(--orange)">♛</span>':''}</td><td>LVL ${p[2]}</td><td class="elo-value">${p[3]}</td><td>${p[4]}</td><td>${p[5]}</td><td>${p[6]}</td></tr>`).join('')}</tbody></table></div></section>`}
function tournamentsPage(){return `<div class="page-title"><div><h1>TOURNAMENTS</h1><p>Соревнуйся за призы, рейтинговые очки и место на сцене.</p></div>${btn('+ CREATE TOURNAMENT','create-tournament','btn btn-hot')}</div><div class="stats-grid">${metric('ACTIVE TOURNAMENTS','12','3 live now')}${metric('TOTAL PRIZE POOL','$498K','Season 1')}${metric('REGISTERED TEAMS','1,248','Across all events')}${metric('YOUR EVENTS','02','1 registration open')}</div><div class="filter-bar"><button class="btn btn-hot tournament-filter" data-filter="ALL">ALL EVENTS</button><button class="btn btn-ghost tournament-filter" data-filter="OPEN">OPEN</button><button class="btn btn-ghost tournament-filter" data-filter="LIVE">LIVE</button><button class="btn btn-ghost tournament-filter" data-filter="UPCOMING">UPCOMING</button><button class="btn btn-ghost tournament-filter" data-filter="FINISHED">FINISHED</button></div><div class="tournament-grid" id="tournament-grid">${tournaments.map(t=>tournamentCard(t)).join('')}</div>`}
function tournamentCard(t){return `<article class="tournament-card" data-status="${t.status}"><div class="tournament-cover" style="background-image:url('${t.cover}')"><span class="status ${t.status==='LIVE'?'live':t.status==='OPEN'?'open':''}">${t.status}</span></div><div class="tournament-body"><h3>${t.name}</h3><p>${t.desc}</p><div class="tournament-facts"><span>PRIZE POOL <b>${t.prize}</b></span><span>${t.teams}</span></div><div class="tournament-facts"><span>${t.format}</span><span>${t.date}</span></div>${btn(t.status==='OPEN'?'JOIN TOURNAMENT':'VIEW DETAILS','tournament','btn btn-hot full')}</div></article>`}
function teamsPage(){return `<div class="page-title"><div><h1>TEAMS & CLANS</h1><p>Создавай состав, приглашай друзей и соревнуйся вместе.</p></div>${btn('+ CREATE TEAM','create-team','btn btn-hot')}</div><div class="stats-grid">${metric('ACTIVE TEAMS','4,281','Across regions')}${metric('YOUR TEAM','No team','Join or create one')}${metric('TEAM MATCHES','142','Top teams')}${metric('RECRUITING','128','Teams looking for players')}</div><div class="filter-bar"><input class="form-input" id="team-search" placeholder="Search teams..." style="max-width:240px"><select class="filter-select" id="team-region"><option>All regions</option><option>Europe</option><option>CIS</option><option>Middle East</option></select><select class="filter-select"><option>Highest ELO</option><option>Most wins</option><option>Most active</option></select></div><div class="team-grid" id="team-grid">${teams.map(teamCard).join('')}</div>`}
function teamCard(t){return `<article class="team-card" data-team="${t.name.toLowerCase()}" data-region="${t.region}"><div class="team-card-head"><div class="team-logo">${t.tag}</div><div><h3>${t.name}</h3><small>${t.tag} · ${t.region}</small></div><span class="status open" style="margin-left:auto">RECRUITING</span></div><p>Competitive roster · Looking for ambitious players to push the next rank.</p><div class="team-facts"><div><small>AVG ELO</small><b>${t.elo}</b></div><div><small>WIN RATE</small><b>${t.wins}</b></div><div><small>ROSTER</small><b>${t.members}</b></div></div><div style="margin-top:13px">${btn('VIEW TEAM →','team-detail','btn btn-ghost full')}</div></article>`}
function newsPage(){return `<div class="page-title"><div><h1>NEWS & UPDATES</h1><p>Последние новости, патчноуты и анонсы FlasH.</p></div><span class="pill">UPDATED DAILY</span></div><section class="panel" style="margin-bottom:13px"><div class="event-banner" style="margin:0;border:0;border-radius:0"><span class="tag">SEASON 01</span><h2>THE COMPETITION STARTS NOW</h2><p>Новый сезон уже здесь: обновлённый рейтинг, новые награды и больше причин играть.</p>${btn('EXPLORE SEASON →','route-events','btn btn-hot')}</div></section><div class="filter-bar"><button class="btn btn-hot news-filter" data-filter="ALL">ALL NEWS</button><button class="btn btn-ghost news-filter" data-filter="SEASON">SEASON</button><button class="btn btn-ghost news-filter" data-filter="UPDATE">UPDATES</button><button class="btn btn-ghost news-filter" data-filter="TOURNAMENT">TOURNAMENTS</button><button class="btn btn-ghost news-filter" data-filter="ESPORTS">ESPORTS</button></div><div class="news-grid" id="news-grid">${news.map(n=>`<article class="news-card" data-tag="${n.tag}"><div class="news-thumb" style="background-image:url('${n.image}')"></div><div class="news-copy"><span class="tag">${n.tag}</span><h3>${n.title}</h3><p>${n.desc}</p><div class="meta-row"><span>◷ ${n.time}</span><span>READ MORE →</span></div></div></article>`).join('')}</div>`}
function statsPage(){return `<div class="page-title"><div><h1>PLAYER STATISTICS</h1><p>Разбирай каждый матч и отслеживай свой прогресс.</p></div><select class="filter-select"><option>Season 1</option><option>All time</option></select></div><div class="stats-grid">${metric('MATCHES','286','+12 this week')}${metric('WIN RATE','58%','+3.2% vs last month')}${metric('K/D RATIO','1.31','+0.08 this month')}${metric('HEADSHOT %','42.8%','+1.4% this month')}</div><div class="content-grid"><div class="column"><section class="panel">${panelHead('ELO HISTORY')}<div style="padding:14px 16px 0;display:flex;justify-content:space-between"><div><small style="color:#848a95">CURRENT ELO</small><div style="font-family:'Barlow Condensed';font-size:28px;margin-top:5px">1,642 <span style="font-size:11px;color:var(--green)">+37</span></div></div><span class="pill good">LAST 30 DAYS</span></div><div class="chart">${[31,36,33,42,38,48,44,53,47,56,61,55,68,63,74,71,82,76,88,80,94,86,100,91,105,98,116,111,126,135].map(v=>`<div class="chart-bar" style="height:${v/1.5}%"></div>`).join('')}</div><div class="chart-labels"><span>SEP 15</span><span>SEP 22</span><span>SEP 29</span><span>OCT 06</span><span>OCT 15</span></div></section><section class="panel">${panelHead('RECENT MATCHES','matches')}<div class="match-history-list">${historyRows(4)}</div></section></div><div class="column"><section class="panel">${panelHead('COMBAT PERFORMANCE')}<div class="quick-play">${[['Kills','1,842','72%'],['Deaths','1,405','58%'],['Assists','522','44%'],['Headshots','788','42.8%'],['MVP Rounds','183','36%']].map(x=>`<div class="select-line" style="display:block"><div style="display:flex;justify-content:space-between;margin-bottom:7px"><span>${x[0]}</span><b style="color:#e8e9ed">${x[1]}</b></div><div class="progress"><span style="width:${x[2]}"></span></div></div>`).join('')}</div></section><section class="panel">${panelHead('FAVORITE MAPS')}<div class="friends-list">${[['Dust 2','68%','74'],['Mirage','61%','52'],['Inferno','57%','48'],['Nuke','51%','32']].map(x=>`<div class="friend-row"><div class="friend-avatar">⌖</div><div class="friend-info"><b>${x[0]}</b><small>${x[2]} matches</small></div><b style="color:#f0f1f4">${x[1]}</b></div>`).join('')}</div></section></div></div>`}
function friendsPage(){return `<div class="page-title"><div><h1>FRIENDS</h1><p>Собирай пати, приглашай игроков и выходи на матч.</p></div>${btn('+ ADD FRIEND','add-friend','btn btn-hot')}</div><div class="stats-grid">${metric('FRIENDS','42','12 online now')}${metric('IN PARTY','1 / 5','Invite players')}${metric('PENDING REQUESTS','3','Review requests')}${metric('RECENT PLAYERS','8','Met in matches')}</div><div class="content-grid"><section class="panel">${panelHead('YOUR FRIENDS')}<div class="filter-bar" style="padding:12px 13px 0"><input class="form-input" id="friend-search" placeholder="Search friends..." style="max-width:230px"><select class="filter-select" id="friend-filter"><option>All</option><option>Online</option><option>In Match</option><option>In Lobby</option></select></div><div class="friends-list" id="friends-list">${friends.map(f=>`<div class="friend-row" data-friend="${f[0].toLowerCase()}" data-status="${f[1]}"><div class="friend-avatar ${f[2]==='busy'?'busy':''}">${f[0][0].toUpperCase()}</div><div class="friend-info"><b>${f[0]}</b><small class="${f[1]==='In Match'?'inmatch':''}">${f[1]}</small></div>${btn('INVITE','invite-friend','btn btn-ghost')}</div>`).join('')}</div></section><div class="column"><section class="panel">${panelHead('YOUR PARTY')}<div class="quick-play"><div style="display:flex;align-items:center;gap:10px;margin-bottom:12px"><div class="friend-avatar">P</div><div class="friend-info"><b>Pashayev <span style="color:var(--green)">●</span></b><small>Party leader</small></div><span class="pill">1 / 5</span></div><div class="empty-state" style="padding:18px"><div class="empty-icon">＋</div><b>Party is waiting</b><p>Пригласи друзей, чтобы собрать состав.</p>${btn('INVITE FRIENDS','add-friend','btn btn-hot')}</div></div></section><section class="panel">${panelHead('PENDING REQUESTS')}<div class="friends-list">${['AimMachine','xShadow','K1ng'].map(n=>`<div class="friend-row"><div class="friend-avatar">${n[0]}</div><div class="friend-info"><b>${n}</b><small>Friend request</small></div><button class="btn btn-hot" data-action="accept-friend">ACCEPT</button></div>`).join('')}</div></section></div></div>`}
function eventsPage(){return `<div class="page-title"><div><h1>EVENTS & MISSIONS</h1><p>Выполняй задания, зарабатывай XP и забирай сезонные награды.</p></div><span class="pill">RESET IN 12H 34M</span></div><div class="event-banner"><span class="tag">WEEKEND EVENT</span><h2>DOUBLE XP WEEKEND</h2><p>Получай вдвое больше опыта за победы до конца события.</p>${btn('VIEW EVENT DETAILS','event-detail','btn btn-hot')}</div><div class="stats-grid">${metric('SEASON XP','12,450','Level 7 progress')}${metric('MISSIONS DONE','18 / 25','3 available today')}${metric('REWARDS CLAIMED','06','2 rewards ready')}${metric('EVENT BONUS','2× XP','Active now')}</div><div class="content-grid"><section class="panel">${panelHead('DAILY MISSIONS')}<div class="quick-play">${[['Play 2 ranked matches','1 / 2','50%','+250 XP'],['Get 15 headshots','11 / 15','73%','+400 XP'],['Win a match on Mirage','0 / 1','0%','+300 XP'],['Play with a friend','0 / 1','0%','+200 XP']].map((m,i)=>`<div class="setting-row"><div style="flex:1"><b>${m[0]}</b><small>${m[1]} complete · ${m[3]}</small><div class="progress" style="margin-top:9px"><span style="width:${m[2]}"></span></div></div>${i===1?btn('CLAIM','claim-reward','btn btn-hot'):btn('TRACK','track-mission','btn btn-ghost')}</div>`).join('')}</div></section><section class="panel">${panelHead('SEASON REWARDS')}<div class="quick-play">${[['LVL 08','Player Card','LOCKED'],['LVL 10','Gold Weapon Skin','LOCKED'],['LVL 15','Rank Badge','LOCKED'],['LVL 20','Season Banner','LOCKED']].map((x,i)=>`<div class="friend-row"><div class="rank-medal" style="width:39px;height:42px;font-size:17px">${['◇','✦','♛','ϟ'][i]}</div><div class="friend-info"><b>${x[1]}</b><small>${x[0]}</small></div><span class="status">${x[2]}</span></div>`).join('')}</div></section></div>`}
function shopPage(){return `<div class="page-title"><div><h1>FL ASH SHOP</h1><p>Эксклюзивные облики, карточки и награды сезона.</p></div><span class="pill">YOUR CREDITS <b style="color:var(--orange)">12,450</b></span></div><div class="event-banner"><span class="tag">PREMIUM MEMBERSHIP</span><h2>UPGRADE YOUR GAME</h2><p>Эксклюзивные профили, сезонные награды, подробная статистика и бонусы опыта.</p>${btn('GET PREMIUM · $4.99','premium','btn btn-hot')}</div><div class="stats-grid">${metric('YOUR CREDITS','12,450','Season currency')}${metric('PREMIUM STATUS','FREE','Upgrade anytime')}${metric('ITEMS OWNED','18','In your inventory')}${metric('REWARD TOKENS','03','Ready to spend')}</div><div class="news-grid">${[['Season 1 Player Card','Exclusive profile card','1,200','assets/news-season.jpg'],['Gold II Rank Badge','Profile badge','800','assets/news-rank.jpg'],['FlasH Championship Banner','Player banner','2,400','assets/tournament.jpg'],['Double XP Boost','2 hours · 2× XP','600','assets/event.jpg'],['Premium Membership','30 days','4,990','assets/hero.jpg'],['Elite Profile Frame','Animated frame','1,800','assets/profile-bg.jpg']].map(x=>`<article class="news-card"><div class="news-thumb" style="background-image:url('${x[3]}')"></div><div class="news-copy"><span class="tag">SEASON 01</span><h3>${x[0]}</h3><p>${x[1]}</p><div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px"><b style="color:var(--orange)">◆ ${x[2]}</b>${btn('BUY','buy-item','btn btn-hot')}</div></div></article>`).join('')}</div>`}
