// Profile-specific interactions are delegated so dynamically switched tabs keep working.
function activateProfileTab(tab){const root=$('#player-profile');if(!root)return;$$('[data-profile-tab]',root).forEach(b=>b.classList.toggle('active',b.dataset.profileTab===tab));$$('[data-profile-view]',root).forEach(v=>v.hidden=v.dataset.profileView!==tab);}
function profileEditor(){modal('EDIT PLAYER PROFILE',`<div class="profile-edit-preview"><img src="${$('#profile-avatar-image')?.src||'assets/profile-bg.jpg'}" alt="Avatar preview"><div><b>Customize your competitive identity</b><small>Changes apply to this local demo session.</small></div></div><label class="field-label">NICKNAME</label><input class="form-input" id="edit-profile-nickname" maxlength="16" minlength="3" pattern="[A-Za-z0-9_]{3,16}" value="${$('#profile-nickname')?.textContent||'Pashayev'}"><small class="field-hint">3–16 characters · letters, numbers and underscore.</small><label class="field-label">COUNTRY</label><select class="form-input" id="edit-profile-country"><option>Germany</option><option>Russia</option><option>Türkiye</option><option>Poland</option><option>United Kingdom</option></select><label class="field-label">BIO · MAX 180 CHARACTERS</label><textarea class="form-input" id="edit-profile-bio" maxlength="180" rows="3">${$('#profile-bio')?.textContent||'Competitive CM player · Entry Fragger · FlasH Elite'}</textarea><label class="field-label">PROFILE VISIBILITY</label><select class="form-input" id="edit-profile-privacy"><option>Public Profile</option><option>Friends Only</option><option>Private</option></select><div class="setting-row"><div><b>Show online status</b><small>Display your current status to other players.</small></div><button class="switch on" data-switch></button></div>`,`${btn('SAVE CHANGES','save-player-profile','btn btn-hot')}${btn('CANCEL','close-modal','btn btn-ghost')}`)}
function openMediaPicker(kind){const isVideo=kind==='banner-video';modal(isVideo?'UPLOAD VIDEO BANNER':kind==='avatar'?'CHANGE AVATAR':'CHANGE PROFILE BANNER',`<p>${isVideo?'Choose an MP4, WebM or other browser-compatible video up to 10 seconds.':'Choose an image from your device. You can preview the crop before applying it.'}</p><label class="field-label">${isVideo?'VIDEO FILE':'IMAGE FILE'}</label><input class="form-input" type="file" id="profile-media-file" accept="${isVideo?'video/mp4,video/webm,video/quicktime':'image/jpeg,image/png,image/webp'}"><div id="profile-media-preview" class="media-preview"><span>PREVIEW WILL APPEAR HERE</span></div><div id="profile-media-status" class="field-hint">Supported: ${isVideo?'MP4 / WEBM · MAX 10 SECONDS':'JPG / JPEG / PNG / WEBP'}</div>${isVideo?'':'<label class="field-label">ZOOM / CROP</label><input id="profile-media-zoom" type="range" min="100" max="200" value="100" class="form-input">'}`,`${btn('APPLY MEDIA','apply-profile-media','btn btn-hot')}${btn('CANCEL','close-modal','btn btn-ghost')}`);const input=$('#profile-media-file');if(input)input.dataset.kind=kind;}
let pendingProfileMedia=null;
document.addEventListener('click',e=>{const tab=e.target.closest('[data-profile-tab]');if(tab){activateProfileTab(tab.dataset.profileTab);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='edit-profile'){e.preventDefault();profileEditor()}if(action==='profile-banner')openMediaPicker('banner');if(action==='profile-video')openMediaPicker('banner-video');if(action==='profile-avatar')openMediaPicker('avatar');if(action==='share-profile'){const url=location.origin+location.pathname+'#player/Pashayev';if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast('PROFILE LINK COPIED',url)).catch(()=>toast('SHARE PROFILE',url));else toast('SHARE PROFILE',url)}if(action==='save-player-profile'){const name=$('#edit-profile-nickname')?.value.trim()||'';if(!/^[A-Za-z0-9_]{3,16}$/.test(name)){toast('INVALID NICKNAME','Используй 3–16 букв, цифр или _.');return}if(name.toLowerCase()!=='pashayev'&&players.some(p=>p[1].toLowerCase()===name.toLowerCase())){toast('NICKNAME ALREADY TAKEN','Этот ник уже занят.');return}$('#profile-nickname').textContent=name;$('#profile-bio').textContent=$('#edit-profile-bio')?.value||'';closeModal();toast('PROFILE UPDATED','Изменения сохранены в текущем демо-сеансе.')}if(action==='match-detail'){modal('MATCH DETAILS',`<div class="select-line"><span>MAP</span><b>${e.target.dataset.map}</b></div><div class="select-line"><span>SCORE</span><b>${e.target.dataset.score}</b></div><div class="select-line"><span>MODE</span><b>Ranked · Europe</b></div><p>Подробная серверная статистика матча недоступна в локальном демо.</p>`,btn('CLOSE','close-modal','btn btn-hot'))}});
document.addEventListener('change',e=>{if(e.target.id==='profile-media-file'){const file=e.target.files?.[0];if(!file)return;const kind=e.target.dataset.kind||'banner';const status=$('#profile-media-status'),preview=$('#profile-media-preview');if(kind==='banner-video'){if(!file.type.startsWith('video/')){status.textContent='UPLOAD FAILED — choose a video file';return}const url=URL.createObjectURL(file),v=document.createElement('video');v.preload='metadata';v.src=url;v.onloadedmetadata=()=>{if(v.duration>10){status.textContent='VIDEO TOO LONG — maximum duration is 10 seconds.';pendingProfileMedia=null;return}pendingProfileMedia={kind,url,file};preview.innerHTML='';const pv=document.createElement('video');pv.src=url;pv.muted=true;pv.autoplay=true;pv.loop=true;pv.playsInline=true;preview.appendChild(pv);status.textContent='PROCESSING… video duration '+v.duration.toFixed(1)+'s · ready to apply';};}else{if(!/^image\/(jpeg|png|webp)$/.test(file.type)){status.textContent='UPLOAD FAILED — use JPG, PNG or WEBP';return}if(file.size>12*1024*1024){status.textContent='UPLOAD FAILED — image must be under 12 MB';return}const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{pendingProfileMedia={kind,url,file};preview.innerHTML='';const pv=document.createElement('img');pv.src=url;preview.appendChild(pv);status.textContent=`PROCESSING… ${img.naturalWidth} × ${img.naturalHeight} · ready to apply`;};img.src=url;}}if(e.target.id==='profile-media-zoom'){const im=$('#profile-media-preview img');if(im)im.style.transform=`scale(${Number(e.target.value)/100})`}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="apply-profile-media"]')){if(!pendingProfileMedia){toast('SELECT A FILE','Сначала выбери корректный файл.');return}const m=pendingProfileMedia;if(m.kind==='avatar'){$('#profile-avatar-image').src=m.url;toast('AVATAR UPDATED','Изображение применено в текущем демо-сеансе.')}else{const holder=$('#profile-banner-media');if(m.kind==='banner-video'){holder.style.backgroundImage='none';holder.innerHTML='';const v=document.createElement('video');v.src=m.url;v.autoplay=true;v.muted=true;v.playsInline=true;v.loop=true;v.className='profile-banner-video';holder.appendChild(v)}else{holder.innerHTML='';holder.style.backgroundImage=`url("${m.url}")`}toast('BANNER SAVED','Медиа применено в текущем демо-сеансе.')}pendingProfileMedia=null;closeModal()}});
document.addEventListener('click',e=>{const period=e.target.closest('[data-elo-period]');if(period){const parent=period.parentElement;$$('[data-elo-period]',parent).forEach(b=>b.classList.toggle('active',b===period));const mult={'7D':7,'30D':30,'3M':90,'6M':180,'1Y':365,'ALL':540}[period.dataset.eloPeriod]||30;const line=$('#elo-line');if(line){const all=[1218,1242,1231,1278,1294,1266,1310,1342,1324,1378,1394,1410,1388,1436,1458,1442,1490,1472,1514,1532,1508,1554,1576,1548,1592,1570,1604,1618,1624,1642],values=all.slice(Math.max(0,all.length-Math.max(5,Math.round(mult/18))));const pts=values.map((v,i)=>`${i*720/(values.length-1)},${150-(v-1200)/5.1}`).join(' ');line.setAttribute('points',pts);const area=$('#elo-area');if(area)area.setAttribute('points',`0,154 ${pts} 720,154`);$('#elo-current').textContent='1,642';}}const result=e.target.closest('[data-match-result-filter]');if(result){$$('[data-match-result-filter]').forEach(b=>b.className=b===result?'btn btn-hot':'btn btn-ghost');filterProfileHistory()}if(e.target.id==='profile-map-filter'||e.target.id==='profile-mode-filter')filterProfileHistory();if(e.target.id==='map-sort'){const grid=$('#profile-map-grid');if(grid){const cards=$$('.profile-map-card',grid);cards.sort((a,b)=>Number(b.dataset[e.target.value])-Number(a.dataset[e.target.value]));cards.forEach(c=>grid.appendChild(c))}}});
function filterProfileHistory(){const filter=$('.profile-match-filters [data-match-result-filter].btn-hot')?.dataset.matchResultFilter||'ALL',map=$('#profile-map-filter')?.value||'all',mode=$('#profile-mode-filter')?.value||'all';$$('#profile-match-history .profile-match-row').forEach(row=>{const result=filter==='ALL'||(filter==='WINS'&&row.dataset.result==='win')||(filter==='LOSSES'&&row.dataset.result==='loss')||(filter==='DRAWS'&&row.dataset.result==='draw');row.style.display=result&&(map==='all'||row.dataset.map===map)&&(mode==='all'||row.dataset.mode===mode)?'':'none'})}
function filterTeams(){const q=$('#team-search')?.value.toLowerCase()||'',r=$('#team-region')?.value||'All regions';$$('#team-grid .team-card').forEach(c=>c.style.display=c.dataset.team.includes(q)&&(r==='All regions'||c.dataset.region===r)?'':'none')}
function filterFriends(){const q=$('#friend-search')?.value.toLowerCase()||'',f=$('#friend-filter')?.value||'All';$$('#friends-list .friend-row').forEach(r=>r.style.display=r.dataset.friend.includes(q)&&(f==='All'||r.dataset.status===f)?'':'none')}
function filterMatches(){const r=$('#match-filter')?.value||'all',m=$('#map-filter')?.value||'all';$$('#matches-table tbody tr').forEach(tr=>tr.style.display=(r==='all'||tr.dataset.result===r)&&(m==='all'||tr.dataset.map===m)?'':'none')}
$('#main-nav').addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a){e.preventDefault();route(a.dataset.route)}});$$('.sidebar-bottom [data-route],.sidebar [data-route]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();route(a.dataset.route)}));$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#notif-btn').addEventListener('click',()=>modal('NOTIFICATIONS',`<div class="friends-list"><div class="friend-row"><div class="friend-avatar">ϟ</div><div class="friend-info"><b>Season 1 is live</b><small>New missions are waiting · 2h ago</small></div></div><div class="friend-row"><div class="friend-avatar">♜</div><div class="friend-info"><b>FlasH Championship</b><small>Registration is open · 5h ago</small></div></div><div class="friend-row"><div class="friend-avatar">↗</div><div class="friend-info"><b>ELO increased</b><small>You gained +24 ELO · Yesterday</small></div></div></div>`,btn('MARK ALL READ','close-modal','btn btn-hot')));$('#message-btn').addEventListener('click',()=>route('friends'));$('#profile-menu').addEventListener('click',()=>route('profile'));$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.trim().toLowerCase();if(!q)return;if(players.some(p=>p[1].toLowerCase().includes(q)))route('leaderboard');else if(teams.some(t=>t.name.toLowerCase().includes(q)))route('teams');else route('news');toast('SEARCH RESULTS',`Результаты поиска для “${e.target.value}”.`)}});$('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}});window.addEventListener('hashchange',render);
