const originalRender=render;
render=function(){if((location.hash.replace('#','').split('/')[0]||'home')==='matchroom'){state.route='matchroom';$('#page-crumb').textContent='MATCH ROOM';$$('[data-route]').forEach(a=>a.classList.remove('active'));$('#page-content').innerHTML=`<div class="page-title"><div><h1>MATCH ROOM</h1><p>Match ID: FH-01-82941 · Server EU-WEST-04</p></div><span class="pill good">● CONNECTED</span></div><div class="content-grid"><div class="column"><section class="panel"><div class="panel-head"><h2>TEAM A · YOUR TEAM</h2><span class="pill">AVG ELO 1,604</span></div><div class="friends-list">${['Pashayev','electroNic','Perfecto','s1mple','NiKo'].map((n,i)=>`<div class="friend-row"><div class="friend-avatar">${n[0]}</div><div class="friend-info"><b>${n}</b><small>LVL ${[7,9,8,12,11][i]} · ${[1642,1588,1562,2841,2730][i]} ELO</small></div><span class="pill good">READY</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>TEAM B · OPPONENTS</h2><span class="pill">AVG ELO 1,580</span></div><div class="friends-list">${['Shadow','Vortex','AimMachine','xShadow','K1ng'].map((n,i)=>`<div class="friend-row"><div class="friend-avatar">${n[0]}</div><div class="friend-info"><b>${n}</b><small>LVL ${[8,8,7,9,10][i]} · ${[1612,1598,1550,1574,1566][i]} ELO</small></div><span class="pill good">READY</span></div>`).join('')}</div></section></div><div class="column"><section class="panel"><div class="tournament-cover" style="height:180px;background-image:url('assets/map-mirage.jpg')"></div><div class="quick-play"><span class="eyebrow">SELECTED MAP</span><h2 style="font-family:'Barlow Condensed';font-size:27px;margin:7px 0">MIRAGE</h2><div class="select-line"><span>SERVER</span><b>EU-WEST-04</b></div><div class="select-line"><span>SERVER IP</span><b>185.12.44.108:27015</b></div><div class="select-line"><span>PING</span><b style="color:var(--green)">24 ms</b></div><div class="select-line"><span>MATCH ID</span><b>FH-01-82941</b></div>${btn('CONNECT TO SERVER →','connect-server','btn btn-hot full')}<div style="margin-top:8px">${btn('COPY SERVER IP','copy-ip','btn btn-ghost full')}</div></div></section></div></div>`;$$('[data-action]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.action==='connect-server')toast('SERVER CONNECTED','В демо-режиме подключение симулируется.');if(b.dataset.action==='copy-ip'){navigator.clipboard?.writeText('185.12.44.108:27015');toast('SERVER IP COPIED','185.12.44.108:27015')}}));$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});return;}originalRender()};
render();
